CREATE OR REPLACE PROCEDURE sp(para_eer_threshold real, para_target_mode text)
LANGUAGE plpgsql
AS $$
DECLARE
    next_id integer;
    rec air_conditioner_info%ROWTYPE;
    phase_change double precision;
    flow_rate double precision;
    working_capacity numeric;
    theoretical_capacity double precision;
    capacity_ratio double precision;
    actual_efficiency double precision;
    actual_cop double precision;
    total_consumption numeric;
    sample_days integer;
    avg_indoor double precision;
    avg_outdoor double precision;
    avg_setting double precision;
    setpoint_flag boolean;
    carnot_cop double precision;
    affected boolean;
    multiplier numeric;
    annual_emissions numeric;
BEGIN
    DELETE FROM carbon_emissions WHERE annual_emissions_tonnes <= 0;
    SELECT COALESCE(MAX(id), 0) + 1 INTO next_id FROM carbon_emissions;

    FOR rec IN SELECT * FROM air_conditioner_info ORDER BY ac_id ASC LOOP
        SELECT phase_change_heat_kj_per_kg, refrigerant_flow_rate_kg_per_s
          INTO phase_change, flow_rate
          FROM refrigerant_properties
         WHERE refrigerant_type = rec.refrigerant_type;

        IF para_target_mode = 'Heating' THEN
            working_capacity := rec.heating_capacity_btu;
        ELSE
            working_capacity := rec.cooling_capacity_btu;
        END IF;

        IF phase_change IS NOT NULL AND flow_rate IS NOT NULL THEN
            theoretical_capacity := phase_change * flow_rate * 3412.14;
            IF working_capacity IS NOT NULL AND working_capacity <> 0 THEN
                capacity_ratio := theoretical_capacity / working_capacity;
            ELSE
                capacity_ratio := NULL;
            END IF;
            IF rec.power_consumption_watts IS NOT NULL AND rec.power_consumption_watts <> 0 THEN
                actual_efficiency := working_capacity / rec.power_consumption_watts;
            ELSE
                actual_efficiency := NULL;
            END IF;
        ELSE
            capacity_ratio := 1.0;
            actual_efficiency := rec.energy_efficiency_ratio;
        END IF;

        IF actual_efficiency IS NULL THEN
            actual_cop := NULL;
        ELSE
            actual_cop := actual_efficiency / 3.412;
        END IF;

        SELECT COALESCE(SUM(energy_consumption_kwh), 0),
               COUNT(DISTINCT record_date),
               AVG(indoor_temperature_celsius),
               AVG(outdoor_temperature_celsius),
               AVG(temperature_setting_celsius)
          INTO total_consumption, sample_days, avg_indoor, avg_outdoor, avg_setting
          FROM energy_consumption
         WHERE ac_id = rec.ac_id AND mode = para_target_mode;

        setpoint_flag := false;
        IF avg_indoor IS NOT NULL AND avg_setting IS NOT NULL THEN
            IF para_target_mode = 'Cooling' AND (avg_indoor - avg_setting) > 2.0 THEN
                setpoint_flag := true;
            ELSIF para_target_mode = 'Heating' AND (avg_setting - avg_indoor) > 2.0 THEN
                setpoint_flag := true;
            END IF;
        END IF;

        carnot_cop := NULL;
        IF avg_indoor IS NOT NULL AND avg_outdoor IS NOT NULL AND avg_outdoor > avg_indoor THEN
            carnot_cop := (avg_indoor + 273.15) / (avg_outdoor - avg_indoor);
        END IF;

        affected := false;
        IF capacity_ratio IS NOT NULL AND capacity_ratio < 0.85 THEN affected := true; END IF;
        IF actual_efficiency IS NOT NULL AND actual_efficiency < para_eer_threshold THEN affected := true; END IF;
        IF carnot_cop IS NOT NULL AND actual_cop IS NOT NULL AND actual_cop < 0.04 * carnot_cop THEN affected := true; END IF;
        IF setpoint_flag THEN affected := true; END IF;

        IF NOT affected THEN
            CONTINUE;
        END IF;

        IF capacity_ratio IS NOT NULL AND capacity_ratio > 0 THEN
            multiplier := 1.0 / capacity_ratio;
        ELSE
            multiplier := 1.0;
        END IF;
        UPDATE energy_consumption
           SET energy_consumption_kwh = energy_consumption_kwh * multiplier
         WHERE ac_id = rec.ac_id AND mode = para_target_mode;

        IF capacity_ratio IS NOT NULL AND capacity_ratio < 0.85 THEN
            UPDATE air_conditioner_info
               SET power_consumption_watts = power_consumption_watts * LEAST(1.5, 1.0 + (1.0 - capacity_ratio))
             WHERE ac_id = rec.ac_id;
        END IF;

        IF sample_days > 0 THEN
            annual_emissions := (total_consumption / sample_days) * 365.0 * 0.000233;
        ELSE
            annual_emissions := rec.power_consumption_watts * 0.000233;
        END IF;

        INSERT INTO carbon_emissions(id, emission_factor, annual_emissions_tonnes)
        VALUES (next_id, 0.000233, annual_emissions);
        next_id := next_id + 1;
    END LOOP;
END;
$$;
